const elec275Route=id=>id==='elec275-notes'||/^elec275-ch-\d+$/.test(id)||id==='elec275-lectures'||/^elec275-lecture-\d+$/.test(id);
const elec275Progress=()=>saved('elec275-ch-notes-v1',{});
let elec275StepState={};
function elec275Citation(text){return `<p class="note-citation"><span>Sources</span>${esc(text)}</p>`}
function elec275ConceptDiagram(section){if(section.lectureDiagram)return elec275LectureDiagram(section);let body='',title='';
 if(section.id==='networks'){title='Three-node circuit drawn as elements between nodes';body=source(110,70,265,'source')+wire('M110 70 H250 M110 265 H700')+resistor(250,70,450,70,'R2 · branch A→B')+resistor(250,70,250,265,'R1')+resistor(450,70,450,265,'R3')+wire('M450 70 H700')+resistor(700,70,700,265,'R4')+node(250,70,'node A')+node(450,70,'node B')+node(450,265,'reference node')+text(585,315,'shape can change · connections cannot','label teal')}
 else if(section.id==='charge-current-voltage'){title='Current through a conductor and voltage between its terminals';body=box(220,115,420,100)+text(430,171,'conducting element','large')+arrow(95,165,210,165)+text(145,142,'i = dq/dt','label teal')+text(215,95,'+','large teal')+text(640,95,'−','large teal')+line(220,100,220,115,'#00695c',3)+line(640,100,640,115,'#00695c',3)+text(430,70,'v = work per charge from − to +','label teal')+text(430,270,'arrow + polarity are chosen references','small muted')}
 else if(section.id==='iv-sources'){title='Ideal voltage and current sources showing which quantity each fixes';body=source(145,65,255,'12 V')+wire('M145 65 H310 M145 255 H310')+text(225,303,'voltage fixed','label teal')+source(550,65,255,'3 A',true)+wire('M550 65 H715 M550 255 H715')+text(630,303,'current fixed','label teal')+text(430,34,'THE LOAD DETERMINES THE OTHER QUANTITY','small muted')}
 else if(section.id==='power-psc'){title='Passive sign convention on a single element';body=wire('M80 165 H330 M530 165 H780')+box(330,115,200,100)+text(352,150,'+','label teal')+text(508,150,'−','label teal')+arrow(140,140,250,140)+text(195,120,'i','label teal')+text(430,178,'v','large teal')+text(430,255,'current enters + ⇒ p = vi','label teal')}
 else if(section.id==='kirchhoff'){title='One-loop circuit illustrating KCL and KVL';body=source(125,70,260,'9 V')+wire('M125 70 H290 M125 260 H690 V70')+resistor(290,70,470,70,'R1 · 1 kΩ')+resistor(470,70,690,70,'R2 · 2 kΩ')+arrow(220,110,300,110)+text(260,140,'3 mA','small teal')+text(430,205,'KVL: +9 − 3 − 6 = 0','large teal')+text(430,250,'KCL: the same 3 mA enters and leaves every node','small')}
 else if(section.id==='resistance-ohm'){title='Resistance depends on material, length, and cross-sectional area';body=box(190,120,480,85)+text(430,170,'resistive material · length ℓ','large')+arrow(110,162,180,162)+text(140,138,'i','label teal')+text(190,102,'+','label teal')+text(670,102,'−','label teal')+text(430,63,'R = ρℓ / A','large teal')+text(430,248,'longer → more R     wider area → less R','label')+text(430,286,'check p = i²R against the part rating','small muted')}
 else if(section.id==='node-voltage'){title='Two-unknown node-voltage network for Example 1.13';body=wire('M90 275 H770')+node(300,80,'v1')+node(590,80,'v2')+resistor(300,80,300,275,'R1 · 1 kΩ')+resistor(300,80,445,80,'R2 · 2 kΩ')+resistor(445,80,590,80,'R3 · 10 kΩ')+resistor(590,80,590,275,'R4 · 2 kΩ')+source(155,80,275,'10 mA',true)+source(725,80,275,'50 mA',true)+arrow(188,222,188,145)+arrow(692,145,692,222)+wire('M155 80 H300 M590 80 H725')+text(430,315,'reference node · 0 V','small muted')}
 else if(section.id==='mesh-current'){title='Three adjacent clockwise mesh currents and a shared resistor';body=wire('M90 80 H770 V260 H90 Z M315 80 V260 M545 80 V260')+resistor(90,80,315,80,'R1')+resistor(315,80,545,80,'R2')+resistor(545,80,770,80,'R3')+resistor(315,80,315,260,'shared')+resistor(545,80,545,260,'shared')+arrow(155,205,225,205)+arrow(385,205,455,205)+arrow(615,205,685,205)+text(190,180,'i1 ↻','label teal')+text(420,180,'i2 ↻','label teal')+text(650,180,'i3 ↻','label teal')+text(430,310,'shared branch current = adjacent mesh-current difference','small muted')}
 else if(section.id==='dependent-sources'){title='Node-voltage circuit with a dependent voltage source for Example 1.20';body=wire('M105 275 H755')+wire('M105 75 H265 M265 75 H505 M505 75 H705')+resistor(265,75,505,75,'R1 · 5 Ω')+resistor(505,75,705,75,'R2 · 2 Ω')+resistor(705,75,705,275,'R3 · 4 Ω')+source(505,75,275,'0.5 A',true)+`<path d="M105 130 L155 180 L105 230 L55 180 Z" fill="#fff" stroke="#263238" stroke-width="3"/>`+wire('M105 75 V130 M105 230 V275')+text(105,170,'+','label teal')+text(105,205,'−','label teal')+text(180,187,'v1 = 2v3','label teal')+node(265,75,'v1')+node(505,75,'v2')+node(705,75,'v3')+text(430,315,'constraint + two KCL equations = three node voltages','small muted')}
 else if(section.id==='series-division'){title='One series loop dividing the source voltage among three resistors';body=source(125,70,260,'v_S')+wire('M125 70 H285 M125 260 H715 V70')+resistor(285,70,430,70,'R1')+resistor(430,70,575,70,'R2')+resistor(575,70,715,70,'R3')+arrow(180,110,255,110)+text(215,142,'one i','label teal')+text(430,205,'v_k = v_S × R_k / (R₁+R₂+R₃)','large teal')+text(430,250,'one loop · one current · the voltage splits by resistance','small muted')}
 else if(section.id==='parallel-division'){title='One current source feeding three resistors in parallel';body=source(115,70,265,'i_S',true)+wire('M115 70 H705 M115 265 H705')+resistor(265,70,265,265,'R1')+resistor(445,70,445,265,'R2')+resistor(625,70,625,265,'R3')+text(350,155,'same v','large teal')+arrow(150,110,225,110)+text(185,140,'i_S splits','small teal')+text(445,308,'one node pair · one voltage · the current splits by conductance','small muted')}
 else if(section.id==='equivalent-resistance'){title='Three-resistor network with three different terminal-pair resistances';body=resistor(170,80,470,80,'6K')+resistor(170,80,320,245,'12K')+resistor(320,245,470,80,'18K')+node(170,80,'a')+node(470,80,'b')+node(320,245,'c')+text(600,110,'R_ab = 6K ∥ 30K = 5K','label teal','start')+text(600,165,'R_ac = 12K ∥ 24K = 8K','label teal','start')+text(600,220,'R_bc = 18K ∥ 18K = 9K','label teal','start')+text(430,315,'equivalence belongs to the pair of nodes, not the circuit','small muted')}
 else if(section.id==='superposition'){title='Two single-source component circuits adding to the full solution';body=box(70,95,190,115)+text(165,140,'12 A alone','label teal')+text(165,175,'v_R = 1.38 V','small')+text(292,160,'+','large teal')+box(325,95,190,115)+text(420,140,'12 V alone','label teal')+text(420,175,'v_R = 4.61 V','small')+text(547,160,'=','large teal')+box(580,95,190,115)+text(675,140,'both sources','label teal')+text(675,175,'v_R = 5.99 V','small')+text(430,268,'each independent source is on exactly once · dependent sources always stay','small muted')}
 else if(section.id==='source-load'){title='Source load line crossing the resistive load law';body=wire('M100 40 V285 M100 285 H780')+wire('M100 65 L720 285','#00695c')+wire('M100 285 L420 146','#263238')+`<circle cx="420" cy="146" r="7" fill="#00695c"/>`+text(78,60,'i_SC','label teal','end')+text(720,308,'v_OC','label teal')+text(430,125,'operating point','label teal','start')+text(120,120,'source: i = (v_S − v)/R₁','small','start')+text(300,265,'load: v = i·R₂','small','start')+text(430,322,'the crossing is the voltage-division result','small muted')}
 else if(section.id==='source-transformation'){title='Thévenin and Norton source forms interchangeable at the same terminals';body=source(150,85,255,'v_T')+resistor(150,85,330,85,'R_T')+wire('M330 85 H400 M150 255 H400')+text(400,70,'a','label')+text(400,272,'b','label')+text(452,170,'⇔','large teal')+source(560,85,255,'i_N',true)+wire('M560 85 H680 M560 255 H680')+resistor(650,85,650,255,'R_N')+text(690,70,'a','label')+text(690,272,'b','label')+text(430,315,'v_T = i_N × R_T · R_T = R_N · same load line','small muted')}
 else if(section.id==='thevenin-norton'){title='Any linear one-port network reduced to one source and one resistor';body=box(70,95,270,140)+text(205,150,'any linear','label')+text(205,180,'one-port network','label')+arrow(365,165,465,165)+source(555,85,255,'v_T')+resistor(555,85,700,85,'R_T')+wire('M700 85 H760 M555 255 H760')+text(760,70,'a','label')+text(760,272,'b','label')+text(430,310,'v_T = v_OC · i_N = i_SC · R_T = v_OC / i_SC','large teal')}
 else if(section.id==='max-power'){title='Load power against load resistance peaking at the match';body=wire('M100 40 V285 M100 285 H780')+wire('M110 280 C 230 130, 320 92, 430 96 C 545 100, 640 175, 760 225','#00695c')+`<path d="M430 96 V285" fill="none" stroke="#00695c" stroke-width="1.6" stroke-dasharray="6 6"/>`+text(430,308,'R_L = R_T','label teal')+text(255,75,'P_max = v_T² / 4R_T','label teal','start')+text(745,308,'R_L','small')+text(60,60,'P_L','small')+text(560,322,'at the match the load takes half the voltage · efficiency 50%','small muted')}
 else if(section.id==='practical-sources-meters'){title='Practical source with internal resistance measured by a loading voltmeter';body=source(115,70,265,'v_S')+resistor(115,70,290,70,'r_S small')+wire('M290 70 H700 M115 265 H700 V70')+resistor(450,70,450,265,'R_o')+resistor(640,70,640,265,'meter r_m ≫')+text(475,140,'v_o sags','label teal')+text(430,312,'voltmeter in parallel: r_m ≫ R · ammeter in series: r_m ≪ R','small muted')}
 else if(section.id==='nonlinear-loads'){title='Straight load line crossing a curved nonlinear device characteristic';body=wire('M100 40 V285 M100 285 H780')+wire('M100 72 L700 285','#00695c')+wire('M100 281 C 280 277, 400 258, 455 226 C 480 210, 487 204, 494 197 C 530 160, 575 95, 610 48','#263238')+`<circle cx="494" cy="197" r="7" fill="#00695c"/>`+text(78,66,'v_T/R_T','label teal','end')+text(700,308,'v_T','label teal')+text(505,175,'operating point','label teal','start')+text(255,255,'device: i_x = f(v_x)','small','start')+text(430,322,'KVL keeps the point on the line · the device law keeps it on the curve','small muted')}
 return body?`<div class="note-concept-diagram" tabindex="0">${svg(body,title)}</div><p class="diagram-hint note-diagram-hint">On a small screen, scroll the circuit sideways to inspect every label.</p>`:'';
}
function elec275Coverage(section){return `<div class="note-objective"><span>${section.outcomeLabel||'TEXTBOOK OUTCOME'}</span><strong>${section.objective}</strong></div><details class="note-coverage"><summary><span>Complete the picture</span><small>${section.coverage.length} supporting ideas from this section</small></summary><div>${section.coverage.map(item=>`<article><h3>${item[0]}</h3><p>${item[1]}</p></article>`).join('')}</div><aside><strong>Trap to catch</strong><p>${section.trap}</p></aside></details>`}

function elec275FieldLens(section){const lens=section.fieldLens;if(!lens)return'';return `<section class="elec275-field-lens" aria-label="Physical meaning and real-world practice"><header><div><span>FROM FARADAY TO THE FIELD</span><h3>One idea, five working perspectives.</h3></div><p>Move from the physical cause to the formula, then see how four different practitioners use the same idea.</p></header><div><article class="physics"><span>PHYSICIST · FARADAY VIEW</span><h4>Why nature behaves this way</h4><p>${lens.physics}</p></article><article class="formula"><span>FORMULA · IN PLAIN ENGLISH</span><h4>What the symbols are claiming</h4><p>${lens.formula}</p></article><article><span>ELECTRICAL ENGINEER</span><h4>Design and prove</h4><p>${lens.engineer}</p></article><article><span>ON-SITE ELECTRICIAN</span><h4>Install, measure, troubleshoot</h4><p>${lens.electrician}</p></article><article><span>COMPUTER TECHNICIAN / INVENTOR</span><h4>Diagnose, prototype, iterate</h4><p>${lens.technician}</p></article></div></section>`}
function elec275Worked(section){if(!section.worked)return'';const label=esc(section.kicker);return `<div class="note-worked"><div class="note-worked-head"><div><span>WORK IT LINE BY LINE</span><h3>${section.worked.title}</h3></div><span class="note-work-count" id="e275-work-count-${section.id}" aria-live="polite"></span></div><div class="note-work-steps" id="e275-work-${section.id}" aria-live="polite"></div><div class="note-work-controls"><button data-e275-back="${section.id}" aria-label="Previous worked step for ${label}">← Back</button><button data-e275-all="${section.id}" aria-label="Show all worked steps for ${label}">Show all</button><button class="primary" data-e275-next="${section.id}" aria-label="Reveal next worked step for ${label}">Reveal next step →</button></div><details class="note-answer"><summary>Final answer · ${label}</summary><p>${section.worked.answer}</p></details></div>`}
function elec275Card(section,index,done){return `<article class="note-card" id="note-${section.id}" tabindex="-1"><header><div><span>${String(index+1).padStart(2,'0')} · ${section.kicker}</span><h2>${section.title}</h2><p>${section.summary}</p></div><label class="note-done"><input type="checkbox" data-e275-done="${section.id}" aria-label="Mark ${section.kicker} studied" ${done[section.id]?'checked':''}> studied</label></header>${elec275Coverage(section)}<div class="note-analogy"><span>REAL-LIFE PICTURE</span><p>${section.analogy}</p></div>${elec275ConceptDiagram(section)}<div class="note-equation">${engrMath(section.math)}</div>${elec275FieldLens(section)}<ul class="note-points">${section.points.map(point=>`<li>${point}</li>`).join('')}</ul>${elec275Worked(section)}<div class="note-check" data-note-check="${section.id}"><span>RETRIEVE IT</span><h3 id="e275-question-${section.id}">${section.check.q}</h3><div role="group" aria-labelledby="e275-question-${section.id}">${section.check.options.map((option,i)=>`<button data-e275-answer="${section.id}:${i}" aria-pressed="false">${String.fromCharCode(65+i)} · ${option}</button>`).join('')}</div><p role="status"></p></div>${elec275Citation(section.citation)}</article>`}
function renderElec275Hub(){const progress=elec275Progress();const cards=[1,2].map(n=>{const sections=ELEC275_CHAPTER_NOTES[n],count=sections.filter(s=>progress[`ch${n}-${s.id}`]).length,source=ELEC275_CHAPTER_SOURCES[n];return `<a class="notes-lecture-card" href="#elec275-ch-${n}"><div><span>CHAPTER ${n}</span><span>${count} / ${sections.length} studied</span></div><h2>${source.title}</h2><p>${source.sub}</p><ul>${sections.map(s=>`<li>${s.kicker.split(' · ')[0]} · ${s.title}</li>`).join('')}</ul><strong>Open Chapter ${n} notes →</strong></a>`}).join('')+`<div class="notes-lecture-card" style="opacity:.55;pointer-events:none" aria-disabled="true"><div><span>CHAPTER 3</span><span>coming next</span></div><h2>AC network analysis</h2><p>Energy-storage elements, time-dependent waveforms, phasors, and impedance.</p><ul><li>In preparation</li></ul><strong>In preparation</strong></div>`;main.innerHTML=`${elecSwitch()}<section class="notes-hero"><div><div class="eyebrow">ELEC 275 · TEXTBOOK NOTES</div><h1>Read the circuit.<br>Name the law.<br>Rebuild it cold.</h1><p>Chapters 1 and 2 of Rizzoni &amp; Kearns, each rebuilt around its textbook outcomes. Every topic connects a circuit picture to the formal rule, a line-by-line example, a trap to catch, and retrieval from memory.</p></div><div class="notes-loop" aria-label="The note-taking learning loop"><span>01</span><strong>Picture</strong><i>→</i><span>02</span><strong>Derive</strong><i>→</i><span>03</span><strong>Retrieve</strong></div></section><div class="notes-lecture-grid">${cards}</div><section class="notes-how"><div><span>HOW TO USE THESE</span><h2>Paper first. Reveal second.</h2></div><ol><li>Read the circuit picture and explain the mechanism aloud.</li><li>Cover the derivation and predict the next line on paper.</li><li>Use the trap and retrieval check to test the reason, not the formula alone.</li><li>Mark “studied” only when you can rebuild the argument without scrolling back.</li></ol></section><section class="notes-reference"><h2>Reference basis</h2><p class="apa-reference">${ELEC_APA}</p><p>The textbook’s table of contents and the Chapter 1–2 learning objectives set the scope and sequence. In-text citations use the book’s printed page numbers. Your PDF is reflowed: printed p. 22 is PDF p. 71; printed p. 80 is PDF p. 168. There is no single page offset. <a href="#elec-references">Open the topic-to-PDF-page map →</a></p><p>The diagrams, analogies, interactions and step-by-step wording are original teaching aids. Every worked number is independently recomputed; the textbook PDF is not republished.</p></section>`;animate('.notes-hero, .notes-lecture-card, .notes-how')}
function renderElec275Lab(n){if(n===2)return renderElec275Lab2();if(n!==1)return'';const diagram=svg(wire('M80 165 H330')+wire('M530 165 H780')+box(330,115,200,100)+text(352,150,'+','label teal')+text(508,150,'−','label teal')+arrow(140,140,250,140)+text(195,120,'i','label teal')+text(430,178,'v','large teal')+text(430,255,'one element · passive sign convention','small muted'),'One element drawn in the passive sign convention: current enters the + terminal');return `<div class="elec275-lab-stack"><section class="notes-lab"><div><div class="eyebrow">INTERACTIVE · POWER REFEREE</div><h2>Move v and i. Call the verdict.</h2><p>This is a preview of §1.4. The arrow enters the + terminal, so compute p = v·i: positive absorbs; negative supplies.</p></div><div class="elec275-referee"><div class="elec275-referee-stage" tabindex="0">${diagram}</div><div class="elec275-referee-controls"><label><span>Voltage v <strong id="elec275-v-val">12 V</strong></span><input id="elec275-v" type="range" min="-24" max="24" step="1" value="12" aria-label="Voltage v in volts"></label><label><span>Current i <strong id="elec275-i-val">2 A</strong></span><input id="elec275-i" type="range" min="-6" max="6" step="0.5" value="2" aria-label="Current i in amperes"></label></div><div class="notes-readout" id="elec275-power-readout" aria-live="polite"></div></div></section><section class="notes-lab elec275-method-lab"><div><div class="eyebrow">INTERACTIVE · METHOD COACH</div><h2>Read the topology before the algebra.</h2><p>Choose what the circuit gives you. The best first move follows the number of nodes or meshes and the placement of its sources.</p></div><div class="method-sort elec275-method-sort"><button data-e275-scenario="nodes">Few nodes</button><button data-e275-scenario="meshes">Few meshes</button><button data-e275-scenario="floating-v">Floating voltage source</button><button data-e275-scenario="shared-i">Shared current source</button><button data-e275-scenario="dependent">Diamond source</button><p class="notes-readout" id="elec275-method-readout" role="status">Choose a circuit feature to see the cleanest route.</p></div></section>${renderElec275LoopWalker()}</div>`}
function renderElec275Lab2(){const dividerDiagram=svg(source(150,70,265,'v_S')+wire('M150 70 H310 M150 265 H660 V70')+resistor(310,70,470,70,'R₁')+resistor(470,70,660,70,'R₂')+arrow(205,110,275,110)+text(240,142,'i','label teal')+text(565,150,'v₂','large teal')+text(405,255,'the same i crosses both resistors','small muted'),'Series divider: one source driving R1 and R2 in a single loop');const loadDiagram=svg(source(150,80,260,'v_T')+resistor(150,80,330,80,'R_T')+wire('M330 80 H430 V110 M150 260 H660 V220 M430 220 H660')+resistor(430,110,430,220,'R_L')+arrow(225,120,295,120)+text(258,150,'i_L','label teal')+text(540,170,'v_L','large teal')+text(430,305,'P_L = v_T² · R_L / (R_T + R_L)²','small muted'),'Thévenin source driving a resistive load');return `<div class="elec275-lab-stack"><section class="notes-lab"><div><div class="eyebrow">INTERACTIVE · DIVIDER EXPLORER</div><h2>Slide the divider. Watch the split.</h2><p>This is §§2.1–2.2 in one loop: one current everywhere, and R₂ keeps exactly its resistance share of the source voltage.</p></div><div class="elec275-referee"><div class="elec275-referee-stage" tabindex="0">${dividerDiagram}</div><div class="elec275-referee-controls"><label><span>Source v_S <strong id="e275d-vs-val">12 V</strong></span><input id="e275d-vs" type="range" min="1" max="24" step="0.5" value="12" aria-label="Source voltage in volts"></label><label><span>Resistor R₁ <strong id="e275d-r1-val">2 kΩ</strong></span><input id="e275d-r1" type="range" min="0.5" max="10" step="0.5" value="2" aria-label="R1 in kilohms"></label><label><span>Resistor R₂ <strong id="e275d-r2-val">4 kΩ</strong></span><input id="e275d-r2" type="range" min="0.5" max="10" step="0.5" value="4" aria-label="R2 in kilohms"></label></div><div class="notes-readout" id="e275d-readout" aria-live="polite"></div></div></section><section class="notes-lab"><div><div class="eyebrow">INTERACTIVE · THÉVENIN & MAX-POWER EXPLORER</div><h2>Match the load. Find the peak.</h2><p>Any linear source is just v_T and R_T (§2.7). Slide R_L through R_T and watch the load power crest at the match — at exactly 50% efficiency (§2.8).</p></div><div class="elec275-referee"><div class="elec275-referee-stage" tabindex="0">${loadDiagram}<svg id="e275t-curve" class="diagram" viewBox="0 0 860 210" role="img" aria-label="Load power curve against load resistance"><path d="M70 20 V180 M70 180 H830" fill="none" stroke="#263238" stroke-width="2.4"/><path id="e275t-curve-path" fill="none" stroke="#00695c" stroke-width="2.6"/><circle id="e275t-curve-dot" r="7" fill="#00695c"/><text x="78" y="34" class="small">P_L</text><text x="824" y="202" text-anchor="end" class="small">R_L →</text></svg></div><div class="elec275-referee-controls"><label><span>Thévenin voltage v_T <strong id="e275t-vt-val">12 V</strong></span><input id="e275t-vt" type="range" min="1" max="24" step="0.5" value="12" aria-label="Thévenin voltage in volts"></label><label><span>Internal R_T <strong id="e275t-rt-val">6 Ω</strong></span><input id="e275t-rt" type="range" min="1" max="24" step="1" value="6" aria-label="Thévenin resistance in ohms"></label><label><span>Load R_L <strong id="e275t-rl-val">6 Ω</strong></span><input id="e275t-rl" type="range" min="0.5" max="48" step="0.5" value="6" aria-label="Load resistance in ohms"></label></div><div class="notes-readout" id="e275t-readout" aria-live="polite"></div></div></section></div>`}
function renderElec275LoopWalker(){const diagram=svg(resistor(140,70,290,70,'R₁ · 1 Ω')+wire('M290 70 H405 M455 70 H570')+'<circle cx="430" cy="70" r="25" fill="white" stroke="#263238" stroke-width="2.4"/>'+arrow(447,70,413,70)+text(430,30,'current source i₁','small')+resistor(570,70,720,70,'R₂ · 1 Ω')+source(720,70,260,'v₂')+resistor(140,260,430,260,'R₄ · 2 Ω')+resistor(430,260,720,260,'R₃ · 2 Ω')+source(140,70,260,'v₁')+node(140,70,'a')+node(720,70,'b')+node(720,260,'c')+node(140,260,'d')+arrow(430,100,380,100)+arrow(680,210,680,160)+arrow(380,230,430,230)+arrow(170,120,170,170)+text(415,122,'i₁','small teal')+text(430,318,'Figure 1.6(b) redrawn · R₁ = R₂ = 1 Ω, R₃ = R₄ = 2 Ω · the source pushes i₁ from b to a','small muted')+'<path id="e275w-hl-bottom" d="M720 260 H140 V70" fill="none" stroke="#00695c" stroke-width="7" stroke-linejoin="round" opacity="0"/><path id="e275w-hl-top" d="M720 260 V70 H140" fill="none" stroke="#00695c" stroke-width="7" stroke-linejoin="round" opacity="0"/><path id="e275w-hl-jump" d="M140 70 L720 260" fill="none" stroke="#1d4ed8" stroke-width="4.5" stroke-dasharray="12 9" opacity="0"/>','Figure 1.6(b): a single ring with nodes a, b, c, d — two voltage sources, one current source forcing i₁ from b to a, and four resistors');return `<section class="notes-lab elec275-loop-lab"><div><div class="eyebrow">INTERACTIVE · LOOP WALKER · FIGURE 1.6(b)</div><h2>Walk the ring. Book every volt.</h2><p>In the textbook: Figure 1.6(b), printed pp. 8–9. KVL says a walk between two nodes books the same voltage on every path — pick a path, then slide the sources and watch the ledger stay balanced.</p></div><div class="elec275-referee"><div class="elec275-referee-stage" tabindex="0">${diagram}</div><div class="elec275-referee-controls"><label><span>Source v₁ <strong id="e275w-v1-val">10 V</strong></span><input id="e275w-v1" type="range" min="0" max="20" step="1" value="10" aria-label="Voltage source v₁ in volts"></label><label><span>Source v₂ <strong id="e275w-v2-val">4 V</strong></span><input id="e275w-v2" type="range" min="0" max="20" step="1" value="4" aria-label="Voltage source v₂ in volts"></label><label><span>Current i₁ <strong id="e275w-i1-val">2 A</strong></span><input id="e275w-i1" type="range" min="0.5" max="5" step="0.5" value="2" aria-label="Current source i₁ in amperes"></label></div><div class="method-sort e275w-walks" role="group" aria-label="Choose which path to walk"><button data-e275w-walk="bottom" aria-pressed="true">Bottom path · c→d→a</button><button data-e275w-walk="top" aria-pressed="false">Top path · c→b→a</button><button data-e275w-walk="jump" aria-pressed="false">Textbook’s jump · a→c</button></div><ol class="notes-ledger" id="e275w-ledger" aria-live="polite"></ol><div class="notes-readout" id="e275w-readout" aria-live="polite"></div></div></section>`}
function drawElec275Steps(section){const host=$(`#e275-work-${section.id}`);if(!host)return;const current=elec275StepState[section.id]||0;host.innerHTML=section.worked.steps.slice(0,current+1).map((s,i)=>`<div class="note-work-step ${i===current?'current':''}"><span>${i+1}</span><div><h4>${s[0]}</h4>${engrMath(s[1])}<p>${s[2]}</p></div></div>`).join('');$(`#e275-work-count-${section.id}`).textContent=`Step ${current+1} of ${section.worked.steps.length}`;document.querySelector(`[data-e275-back="${section.id}"]`).disabled=current===0;document.querySelector(`[data-e275-next="${section.id}"]`).disabled=current===section.worked.steps.length-1;document.querySelector(`[data-e275-all="${section.id}"]`).disabled=current===section.worked.steps.length-1;}
function wireElec275Lab(n){if(n===2){wireElec275Lab2();return}if(n!==1)return;const vEl=$('#elec275-v'),iEl=$('#elec275-i');if(vEl&&iEl){const draw=()=>{const v=+vEl.value,i=+iEl.value,p=v*i;$('#elec275-v-val').textContent=fmt(v)+' V';$('#elec275-i-val').textContent=fmt(i)+' A';const verdict=p>0?`absorbing ${fmt(p)} W`:p<0?`supplying ${fmt(-p)} W`:'transferring no power';$('#elec275-power-readout').innerHTML=`<strong>p = v·i = (${fmt(v)}) × (${fmt(i)}) = ${fmt(p)} W.</strong> The current reference enters the + terminal, so this element is ${verdict}. If only the current arrow were reversed, signed i and v·i would change sign and the formula would become p = −vi; the physical verdict would stay the same.`};vEl.oninput=draw;iEl.oninput=draw;draw()}
 const scenarios={nodes:['Start with node voltage.','KCL uses one unknown per non-reference node; current sources enter those equations directly.'],meshes:['Start with mesh current.','KVL uses one unknown per mesh and is efficient for planar circuits with voltage sources.'],'floating-v':['Use a supernode.','Enclose both source terminals, write KCL for the boundary, then add the source-voltage equation.'],'shared-i':['Use a supermesh.','Write the mesh-current difference imposed by the source, then write KVL around the outer boundary.'],dependent:['Keep the normal method and add a constraint.','Treat the diamond like its source type in KCL or KVL, then substitute the controlling relationship.']};main.querySelectorAll('[data-e275-scenario]').forEach(button=>{button.setAttribute('aria-pressed','false');button.onclick=()=>{main.querySelectorAll('[data-e275-scenario]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));const result=scenarios[button.dataset.e275Scenario];$('#elec275-method-readout').innerHTML=`<strong>${result[0]}</strong>${result[1]}`}});wireElec275LoopWalker()}
function wireElec275Lab2(){const vs=$('#e275d-vs'),r1=$('#e275d-r1'),r2=$('#e275d-r2');if(vs&&r1&&r2){const drawD=()=>{const v=+vs.value,a=+r1.value,b=+r2.value,i=v/(a+b),v1=i*a,v2=i*b,frac=b/(a+b);$('#e275d-vs-val').textContent=fmt(v)+' V';$('#e275d-r1-val').textContent=fmt(a)+' kΩ';$('#e275d-r2-val').textContent=fmt(b)+' kΩ';$('#e275d-readout').innerHTML=`<strong>i = ${fmt(i)} mA, v₁ = ${fmt(v1)} V, v₂ = ${fmt(v2)} V.</strong> The fraction R₂/(R₁+R₂) = ${fmt(b)}/(${fmt(a)}+${fmt(b)}) = ${fmt(frac,3)} of the source sits across R₂, and the same ${fmt(i)} mA crosses both resistors — one current, divided voltage.`};vs.oninput=drawD;r1.oninput=drawD;r2.oninput=drawD;drawD()}
 const vt=$('#e275t-vt'),rt=$('#e275t-rt'),rl=$('#e275t-rl');if(vt&&rt&&rl){const drawT=()=>{const v=+vt.value,t=+rt.value,l=+rl.value,i=v/(t+l),vl=i*l,p=i*i*l,pmax=v*v/(4*t),eff=100*l/(t+l);$('#e275t-vt-val').textContent=fmt(v)+' V';$('#e275t-rt-val').textContent=fmt(t)+' Ω';$('#e275t-rl-val').textContent=fmt(l)+' Ω';const verdict=l===t?`Matched: R_L = R_T = ${fmt(t)} Ω, so the load takes the maximum possible power — and the source dissipates an equal share inside R_T.`:`R_L is ${fmt(l/t,2)}× R_T; the peak ${fmt(pmax)} W would arrive at R_L = ${fmt(t)} Ω (this load is at ${fmt(100*p/pmax,1)}% of the peak).`;$('#e275t-readout').innerHTML=`<strong>i_L = ${fmt(i)} A, v_L = ${fmt(vl)} V, P_L = ${fmt(p)} W.</strong> ${verdict} Efficiency = ${fmt(eff,1)}%.`;const path=$('#e275t-curve-path'),dot=$('#e275t-curve-dot');if(path&&dot){const points=[];for(let k=0;k<=60;k++){const r=48*k/60,pr=v*v*r/((t+r)*(t+r));points.push(`${k?'L':'M'}${(70+760*r/48).toFixed(1)} ${(180-155*pr/(pmax*1.05)).toFixed(1)}`)}path.setAttribute('d',points.join(' '));dot.setAttribute('cx',(70+760*l/48).toFixed(1));dot.setAttribute('cy',(180-155*p/(pmax*1.05)).toFixed(1))}};vt.oninput=drawT;rt.oninput=drawT;rl.oninput=drawT;drawT()}}
function wireElec275LoopWalker(){const v1El=$('#e275w-v1'),v2El=$('#e275w-v2'),i1El=$('#e275w-i1');if(!v1El||!v2El||!i1El)return;let mode='bottom';const sgn=x=>(x>=0?'+':'−')+fmt(Math.abs(x)),vm=x=>(x<0?'−':'')+fmt(Math.abs(x));const totals=()=>{const v1=+v1El.value,v2=+v2El.value,i1=+i1El.value,vs=v2-v1-i1*6;return{v1,v2,i1,vs,bottom:v1+i1*4,top:v2-i1*2-vs,ring:vs+v1+i1*6-v2}};const ledger=t=>{const r3=t.i1*2,r4=t.i1*2,rows=[],row=(rule,detail)=>rows.push(`<li><span>${rows.length+1}</span><strong>${rule}</strong><p>${detail}</p></li>`);if(mode==='bottom'){row('Start at c','reference zero · total 0 V');row('Cross R₃ against the current',`rise i₁R₃ = ${sgn(r3)} V · total ${vm(r3)} V`);row('Cross R₄ against the current',`rise i₁R₄ = ${sgn(r4)} V · total ${vm(r3+r4)} V`);row('Cross v₁ from − to +',`rise v₁ = ${sgn(t.v1)} V · total ${vm(t.bottom)} V`);rows.push(`<li class="notes-ledger-final"><span>${rows.length+1}</span><strong>Arrive at a · v_ac = ${vm(t.bottom)} V</strong><p>The bottom path books the whole climb in one walk.</p></li>`)}else if(mode==='top'){row('Start at c','reference zero · total 0 V');row('Cross v₂ from − to +',`rise v₂ = ${sgn(t.v2)} V · total ${vm(t.v2)} V`);row('Cross R₂ with the current',`drop i₁R₂ = ${sgn(-t.i1)} V · total ${vm(t.v2-t.i1)} V`);row('Cross the current source b→a',`it promises current, not voltage. Ring KVL fixes it: v_s = v₂ − v₁ − i₁(R₁+R₂+R₃+R₄) = ${vm(t.vs)} V — a drop of ${vm(t.vs)} V in the b→a direction flips sign → contribution ${sgn(-t.vs)} V · total ${vm(t.v2-t.i1-t.vs)} V`);row('Cross R₁ with the current',`drop i₁R₁ = ${sgn(-t.i1)} V · total ${vm(t.top)} V`);rows.push(`<li class="notes-ledger-final"><span>${rows.length+1}</span><strong>Arrive at a · v_ac = ${vm(t.top)} V</strong><p>Same destination as the bottom path — it had to be.</p></li>`)}else{row('Start at a','reference zero · total 0 V');row('Jump a→c through open space','the unknown drop v_ac → contribution −v_ac · total −v_ac');row('Cross R₃ against the current',`rise i₁R₃ = ${sgn(r3)} V · total −v_ac + ${fmt(r3)} V`);row('Cross R₄ against the current',`rise i₁R₄ = ${sgn(r4)} V · total −v_ac + ${fmt(r3+r4)} V`);row('Cross v₁ from − to +',`rise v₁ = ${sgn(t.v1)} V · total −v_ac + ${fmt(t.bottom)} V`);rows.push(`<li class="notes-ledger-final"><span>${rows.length+1}</span><strong>Back at a — the loop must total zero: −v_ac + ${fmt(r3)} + ${fmt(r4)} + ${fmt(t.v1)} = 0 → v_ac = ${vm(t.bottom)} V</strong><p>The jump is legal — voltage exists between any two nodes.</p></li>`)}return rows.join('')};const draw=()=>{const t=totals();$('#e275w-v1-val').textContent=fmt(t.v1)+' V';$('#e275w-v2-val').textContent=fmt(t.v2)+' V';$('#e275w-i1-val').textContent=fmt(t.i1)+' A';$('#e275w-ledger').innerHTML=ledger(t);$('#e275w-readout').innerHTML=`<strong>bottom = ${vm(t.bottom)} V · top = ${vm(t.top)} V · ring KVL sum = ${vm(t.ring)} V</strong> The two paths agree ✓ — v_ac is the same no matter which way you walk. The ring is the circuit's only mesh; the triangle is a loop, not a mesh.`};const trace=()=>{['bottom','top','jump'].forEach(k=>{const p=$('#e275w-hl-'+k);if(!p)return;if(k!==mode){p.setAttribute('opacity','0');return}p.setAttribute('opacity','1');if(motion&&window.gsap){if(k==='jump')gsap.fromTo(p,{opacity:0},{opacity:1,duration:.6});else if(p.getTotalLength){const len=p.getTotalLength();gsap.fromTo(p,{strokeDasharray:len,strokeDashoffset:len},{strokeDashoffset:0,duration:1.1,ease:'power1.inOut'})}}})};const setMode=m=>{mode=m;main.querySelectorAll('[data-e275w-walk]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.e275wWalk===m)));draw();trace()};v1El.oninput=draw;v2El.oninput=draw;i1El.oninput=draw;main.querySelectorAll('[data-e275w-walk]').forEach(b=>b.onclick=()=>setMode(b.dataset.e275wWalk));draw();trace()}
function wireElec275Notes(n,sections){const refreshProgress=()=>{const progress=elec275Progress(),count=sections.filter(s=>progress[`ch${n}-${s.id}`]).length,percent=count/sections.length*100;$('#elec275-progress').textContent=`${count} / ${sections.length} studied`;const bar=$('#elec275-progress-bar');if(bar){bar.setAttribute('aria-valuenow',String(count));bar.querySelector('span').style.width=percent+'%'}};sections.forEach(section=>{if(section.worked){drawElec275Steps(section);document.querySelector(`[data-e275-back="${section.id}"]`).onclick=()=>{elec275StepState[section.id]=Math.max(0,elec275StepState[section.id]-1);drawElec275Steps(section)};document.querySelector(`[data-e275-next="${section.id}"]`).onclick=()=>{elec275StepState[section.id]=Math.min(section.worked.steps.length-1,elec275StepState[section.id]+1);drawElec275Steps(section);if(motion&&window.gsap)gsap.from(`#e275-work-${section.id} .note-work-step:last-child`,{y:10,opacity:0,duration:.35})};document.querySelector(`[data-e275-all="${section.id}"]`).onclick=()=>{elec275StepState[section.id]=section.worked.steps.length-1;drawElec275Steps(section)}}});main.querySelectorAll('[data-e275-done]').forEach(input=>input.onchange=()=>{const progress=elec275Progress();progress[`ch${n}-${input.dataset.e275Done}`]=input.checked;persist('elec275-ch-notes-v1',progress);refreshProgress()});main.querySelectorAll('[data-e275-answer]').forEach(button=>button.onclick=()=>{const [id,indexText]=button.dataset.e275Answer.split(':'),section=sections.find(s=>s.id===id),index=+indexText,host=button.closest('.note-check');host.querySelectorAll('button').forEach(b=>{b.classList.remove('correct','wrong');b.setAttribute('aria-pressed',String(b===button))});button.classList.add(index===section.check.answer?'correct':'wrong');host.querySelector('[role="status"]').innerHTML=`<strong>${index===section.check.answer?'Exactly.':'Try again.'}</strong> ${section.check.why}`});main.querySelectorAll('[data-e275-jump]').forEach(a=>a.onclick=e=>{e.preventDefault();const target=$(`#note-${a.dataset.e275Jump}`);if(target){target.scrollIntoView({behavior:'instant'});target.focus({preventScroll:true})}});wireElec275Lab(n)}
function renderElec275Chapter(n){const source=ELEC275_CHAPTER_SOURCES[n],trail=ELEC275_CHAPTER_TRAILS[n],sections=ELEC275_CHAPTER_NOTES[n],allProgress=elec275Progress(),done=Object.fromEntries(sections.map(s=>[s.id,allProgress[`ch${n}-${s.id}`]])),count=Object.values(done).filter(Boolean).length,percent=count/sections.length*100;elec275StepState=Object.fromEntries(sections.filter(s=>s.worked).map(s=>[s.id,0]));main.innerHTML=`${elecSwitch()}<nav class="notes-breadcrumb"><a href="#elec275-notes">← All textbook notes</a><div>${trail.breadcrumb}</div></nav><section class="lecture-head"><div class="eyebrow">ELEC 275 · CHAPTER ${n} · TEXTBOOK NOTES</div><h1>${source.title}</h1><p>${source.sub}</p><div class="lecture-meta"><span>${source.range}</span><span>${source.problems}</span><span id="elec275-progress">${count} / ${sections.length} studied</span></div></section><section class="elec275-command"><div><div class="eyebrow">${trail.command.eyebrow}</div><h2>${trail.command.title}</h2><p>${trail.command.body}</p></div><div><div class="elec275-progress-track" id="elec275-progress-bar" role="progressbar" aria-label="Chapter ${n} topics studied" aria-valuemin="0" aria-valuemax="${sections.length}" aria-valuenow="${count}"><span style="width:${percent}%"></span></div><div class="elec275-route-grid">${trail.command.routes.map(r=>`<a href="#note-${r[0]}" data-e275-jump="${r[0]}"><span>${r[1]}</span><strong>${r[2]}</strong></a>`).join('')}</div></div></section><nav class="lecture-jumps elec275-chapter-jumps" aria-label="Chapter ${n} concepts">${sections.map((s,i)=>`<a href="#note-${s.id}" data-e275-jump="${s.id}"><span>${String(i+1).padStart(2,'0')}</span><strong>${s.kicker.split(' · ')[0]}</strong>${s.title}</a>`).join('')}</nav>${renderElec275Lab(n)}<section class="lecture-notes">${sections.map((s,i)=>elec275Card(s,i,done)).join('')}</section><section class="elec275-synthesis"><div><div class="eyebrow">${trail.synthesis.eyebrow}</div><h2>${trail.synthesis.title}</h2><p>${trail.synthesis.body}</p></div><ol>${trail.synthesis.steps.map((s,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><strong>${s[0]}</strong><p>${s[1]}</p></li>`).join('')}</ol></section><section class="elec275-homework"><div><div class="eyebrow">FROM NOTES TO PAPER</div><h2>A curated homework ladder.</h2><p>${trail.homework.body}</p></div><div>${trail.homework.bands.map(b=>`<article><span>${b[0]}</span><strong>${b[1]}</strong><p>${b[2]}</p></article>`).join('')}</div></section><section class="notes-reference"><div class="eyebrow">COMPLETE REFERENCES</div><h2>Sources for Chapter ${n}</h2><p class="apa-reference">${ELEC_APA}</p><p>${trail.reference}</p></section><div class="engr-bottom-nav"><a href="#elec275-notes">All textbook notes</a><a href="#quiz">Quiz desk →</a>${trail.bottom}</div>`;wireElec275Notes(n,sections);animate('.lecture-head, .note-card')}
function renderElec275Notes(){const match=activeId.match(/^elec275-ch-(\d+)$/);if(match&&ELEC275_CHAPTER_NOTES[+match[1]]){document.title=`ELEC 275 Chapter ${match[1]} notes · Ash’s Study Lab`;$('#course-label').textContent=`ELEC 275 / CHAPTER ${match[1]} · TEXTBOOK NOTES`;renderElec275Chapter(+match[1])}else{document.title='ELEC 275 textbook notes · Ash’s Study Lab';$('#course-label').textContent='ELEC 275 / TEXTBOOK NOTES';renderElec275Hub()}}
